let studioTranslating=false;
function studioTranslate(){if(studioTranslating)return;studioTranslating=true;const walk=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walk.nextNode()){const p=n.parentElement;if(!p||p.closest('script,style,textarea,input,#projectName,.clip-label,.clip-name,.bin-name,.media-name'))continue;const raw=n.nodeValue,word=raw.trim();if(studioWords[word])n.nodeValue=raw.replace(word,studioWords[word]);}for(const node of document.querySelectorAll('[title],[aria-label],[placeholder]'))for(const attr of ['title','aria-label','placeholder']){const value=node.getAttribute(attr);if(studioWords[value])node.setAttribute(attr,studioWords[value]);}studioTranslating=false;}
let studioLocaleTimer;new MutationObserver(()=>{if(studioLocaleTimer)return;studioLocaleTimer=setTimeout(()=>{studioLocaleTimer=null;studioTranslate();},80);}).observe(document.body,{childList:true,subtree:true});studioTranslate();
